import {CATEGORIES, PROJECTS, DEMO_TASKS, DEMO_HABITS, DEMO_SUGGESTIONS, STORAGE_KEY, SCHEMA_VERSION} from './data.js';
import {icon,hydrateIcons} from './icons.js';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto?.randomUUID?.()||`id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const localDay=(d=new Date())=>{const x=new Date(d.getTime()-d.getTimezoneOffset()*60000);return x.toISOString().slice(0,10)};
const today=()=>localDay();
const fromDay=(s)=>new Date(`${s}T12:00:00`);
const backDays=(i)=>{const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-i);return localDay(d)};
const fmtDay=(s)=>s?fromDay(s).toLocaleDateString(undefined,{month:'short',day:'numeric'}):'';
const percent=(n,total)=>total?Math.round(100*n/total):0;
const defaultPrefs={showSummary:true,showFocus:true,showProjects:true,showHabits:true,showReview:true,showEmail:true,showPrivacy:true,showProjectProgress:true,compactRows:false,focusCount:5,defaultView:'dashboard'};
const baseCategory=c=>{const legacy={'Home & Garage':'Home','Bikes':'Mountain Bikes','Vehicles':'Vehicles','Outdoor & Snow':'Outdoor & Snow','Finance & Admin':'Finances','Personal & Health':'Fitness','Work & Projects':'Work','Errands & Shopping':'Inbox'};return legacy[c]||c||'Inbox'};
const normalizePrefs=p=>{const r={...defaultPrefs};for(const [key,value] of Object.entries(p||{}))if(key in r){if(typeof r[key]==='boolean'&&typeof value==='boolean')r[key]=value;else if(key==='focusCount'&&[3,5,8,10].includes(Number(value)))r[key]=Number(value);else if(key==='defaultView'&&['dashboard','tasks','projects','habits','review'].includes(value))r[key]=value;}return r;};
const normalizeCategory=c=>({name:String(c?.name||'Inbox').slice(0,70),icon:String(c?.icon||'grid').slice(0,30),color:/^#[\da-fA-F]{6}$/.test(c?.color||'')?c.color:'#8eafb4',visible:c?.visible!==false});
const normalizeProject=p=>({id:String(p?.id||uid()).slice(0,90),name:String(p?.name||'Untitled project').slice(0,90),category:baseCategory(p?.category||'Inbox')});
const normalizeTask=t=>({id:String(t?.id||uid()).slice(0,90),title:String(t?.title||'Untitled task').slice(0,260),category:baseCategory(t?.category||'Inbox'),projectId:t?.projectId?String(t.projectId).slice(0,90):null,priority:['urgent','high','normal','low'].includes(t?.priority)?t.priority:'normal',status:t?.status==='completed'?'completed':'open',reviewed:!!t?.reviewed,dueDate:/^\d{4}-\d{2}-\d{2}$/.test(t?.dueDate||'')?t.dueDate:null,notes:String(t?.notes||'').slice(0,5000),source:String(t?.source||'Manual').slice(0,100),parentId:t?.parentId||null,indent:Number(t?.indent)||0,sourceIndex:Number(t?.sourceIndex)||0,possibleDuplicate:!!t?.possibleDuplicate,completedAt:t?.completedAt||null,updatedAt:t?.updatedAt||null});
const normalizeHabit=h=>({id:String(h?.id||uid()).slice(0,90),name:String(h?.name||'Activity').slice(0,90),target:Math.min(7,Math.max(1,Number(h?.target)||3)),type:['habit','workout','ride'].includes(h?.type)?h.type:(/ride|mountain bike/i.test(h?.name||'')?'ride':/strength|workout|training/i.test(h?.name||'')?'workout':'habit')});
const normalizeSuggestion=s=>({id:String(s?.id||uid()).slice(0,90),type:['email','calendar','import'].includes(s?.type)?s.type:'email',title:String(s?.title||'Untitled suggestion').slice(0,260),detail:String(s?.detail||'').slice(0,300),category:baseCategory(s?.category||'Inbox'),projectId:s?.projectId||null,priority:['urgent','high','normal','low'].includes(s?.priority)?s.priority:'normal',status:['pending','approved','dismissed'].includes(s?.status)?s.status:'pending'});
function demoState(){
 const history={};
 // Sample-only history, deterministic with respect to the current day.
 [1,2,3,5,6,8,9,10,12,13,16,17,18,20,22,24,25,27].forEach(i=>{(history['habit-workout'] ||= {})[backDays(i)]=true;});
 [1,4,7,9,12,15,18,21,24].forEach(i=>{(history['habit-ride'] ||= {})[backDays(i)]=true;});
 [1,2,3,4,5,8,9,10,11,12,15,16,17,18,19,22,23,24,25,26].forEach(i=>{(history['habit-review'] ||= {})[backDays(i)]=true;});
 return {schemaVersion:SCHEMA_VERSION,source:'demo',preferences:{...defaultPrefs},categories:CATEGORIES.map(normalizeCategory),projects:PROJECTS.map(normalizeProject),tasks:DEMO_TASKS.map(normalizeTask),habits:DEMO_HABITS.map(normalizeHabit),history,suggestions:DEMO_SUGGESTIONS.map(normalizeSuggestion),importedAt:null};
}
function restore(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return demoState();const s=JSON.parse(raw);return {...demoState(),...s,schemaVersion:SCHEMA_VERSION,preferences:normalizePrefs(s.preferences),categories:(s.categories||CATEGORIES).map(normalizeCategory),projects:(s.projects||PROJECTS).map(normalizeProject),tasks:(s.tasks||[]).map(normalizeTask),habits:(s.habits||DEMO_HABITS).map(normalizeHabit),history:s.history||{},suggestions:(s.suggestions||[]).map(normalizeSuggestion)};}catch(e){console.warn(e);return demoState();}}
let store=restore(),view=store.preferences.defaultView,filter='open',categoryFilter='all',projectFilter='all',search='',showLimit=120,reviewShowLimit=50,toastTimer,pendingImport=null;
const persist=()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(store));}catch(e){toast('Storage full. Export a backup before editing more.',true);console.error(e);}};
function toast(msg,error=false){const el=$('#toast');if(!el)return;el.textContent=msg;el.className=error?'show error':'show';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',3600);}
const openTasks=()=>store.tasks.filter(t=>t.status==='open');
const doneTasks=()=>store.tasks.filter(t=>t.status==='completed');
const unreviewed=()=>store.tasks.filter(t=>t.status==='open'&&!t.reviewed);
const pendingSuggestions=()=>store.suggestions.filter(s=>s.status==='pending');
const catByName=name=>store.categories.find(c=>c.name===name)||{name,icon:'grid',color:'#97a9ba',visible:true};
const projectById=id=>store.projects.find(p=>p.id===id);
const normTitle=t=>String(t||'').toLowerCase().replace(/[^a-z0-9 ]/g,'').replace(/\s+/g,' ').trim();
const projectStats=id=>{const tasks=store.tasks.filter(t=>t.projectId===id);return {total:tasks.length,done:tasks.filter(t=>t.status==='completed').length,open:tasks.filter(t=>t.status==='open').length,pct:percent(tasks.filter(t=>t.status==='completed').length,tasks.length)};};
const habitEntry=(id,day=today())=>store.history?.[id]?.[day]||null;
const habitDone=(id,day=today())=>{const v=habitEntry(id,day);return v===true||(typeof v==='object'&&v?.completed===true);};
const habitStats=id=>{const days28=Array.from({length:28},(_,i)=>backDays(i));const fourWeek=days28.filter(d=>habitDone(id,d)).length;const weeks=Array.from({length:12},(_,i)=>{const days=Array.from({length:7},(_,j)=>backDays((11-i)*7+j));return {label:i===11?'Now':`${11-i}w`,count:days.filter(d=>habitDone(id,d)).length};});return {fourWeek,weeks};};
const habitCount=(id,days=7)=>Array.from({length:days},(_,i)=>habitDone(id,backDays(i))?1:0).reduce((a,b)=>a+b,0);
const habitStreak=id=>{let n=0,offset=habitDone(id)?0:1;for(let i=offset;i<365;i++){if(!habitDone(id,backDays(i)))break;n++;}return n;};
const iconLabel=(name)=>icon(name,17);
const sortTasks=arr=>[...arr].sort((a,b)=>((b.priority==='urgent'?4:b.priority==='high'?3:b.priority==='normal'?2:1)-(a.priority==='urgent'?4:a.priority==='high'?3:a.priority==='normal'?2:1))||(a.dueDate||'9999').localeCompare(b.dueDate||'9999')||(a.sourceIndex||0)-(b.sourceIndex||0));
function heading(eyebrow,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p class="heading-subtitle">${esc(desc)}</p></div>${action}</div>`;}
function demoLabel(){return store.source==='demo'?`<div class="prototype-banner">${icon('info',18)} <div><b>Sample workspace</b><p>Project progress, check-in history and AI proposals are examples. Your OneNote import stays private until you choose to load it.</p></div><button class="btn btn-outline" data-action="import">Import tasks</button></div>`:'';}
function migrationBanner(){if(store.source!=='demo'||!localStorage.getItem('task-forge-v3-prototype'))return '';return `<div class="prototype-banner">${icon('info',18)}<div><b>Existing v3 workspace found</b><p>You can copy your current v3 data into this beta without changing or deleting the original.</p></div><button class="btn btn-outline" data-action="migrate-v3">Review copy</button></div>`;}
function taskRow(t){const done=t.status==='completed',p=projectById(t.projectId),color=catByName(p?.category||t.category).color;return `<div class="task-row category-tinted ${done?'completed':''} ${store.preferences.compactRows?'compact-row':''}" style="--category-color:${color}">
 <button class="task-check ${done?'is-done':''}" data-action="task-toggle" data-id="${esc(t.id)}" aria-label="${done?'Reopen':'Complete'} ${esc(t.title)}">${done?icon('check',15):''}</button>
 <div class="task-body" data-action="task-edit" data-id="${esc(t.id)}" role="button" tabindex="0"><div class="task-title">${esc(t.title)}</div><div class="task-meta"><span class="plain-chip category-chip"><span class="chip-dot"></span>${esc(p?.name||t.category)}</span>${!t.reviewed&&!done?'<span class="review-chip">Review</span>':''}${t.dueDate?`<span class="date-text">${fmtDay(t.dueDate)}</span>`:''}</div></div>
 <div class="task-tail">${['high','urgent'].includes(t.priority)?`<span class="pill prio high">${esc(t.priority)}</span>`:''}<button class="icon-button" data-action="task-edit" data-id="${esc(t.id)}" aria-label="Edit">${icon('chevron',17)}</button></div></div>`;}
function focusPanel(){const tasks=sortTasks(openTasks()).slice(0,store.preferences.focusCount);return `<section class="panel focus-panel"><div class="panel-heading"><div><span class="eyebrow">ACTION LIST</span><h2>Next up</h2></div><button class="inline-link" data-nav="tasks">All tasks ${icon('arrow',15)}</button></div>${tasks.length?`<div class="task-rows">${tasks.map(taskRow).join('')}</div>`:`<div class="quiet-empty">No open tasks.</div>`}</section>`;}
function projectCard(p,small=false){const st=projectStats(p.id),color=catByName(p.category).color;return `<button style="--category-color:${color}" class="progress-project category-tinted ${small?'small':''}" data-action="project-open" data-id="${esc(p.id)}"><div class="progress-project-top"><span>${esc(p.name)}</span><b>${st.total?`${st.pct}%`:'—'}</b></div><div class="progress-track"><div style="width:${st.pct}%"></div></div><div class="progress-project-foot">${st.open} open · ${st.done} completed <span>${esc(p.category)}</span></div></button>`;}
function projectsPanel(){const eligible=store.projects.filter(p=>catByName(p.category).visible).slice(0,6);return `<section class="panel"><div class="panel-heading"><div><span class="eyebrow">ONE PLACE FOR EVERYTHING</span><h2>Project progress</h2></div><button class="inline-link" data-nav="projects">See projects ${icon('arrow',15)}</button></div><div class="project-progress-list">${eligible.map(p=>projectCard(p,true)).join('')}</div></section>`;}
function habitTodayCard(h){const d=habitDone(h.id),n=habitCount(h.id);return `<div class="routine-line"><button class="routine-checkbox ${d?'checked':''}" data-action="habit-toggle" data-id="${esc(h.id)}" aria-label="${d?'Uncheck':'Check'} ${esc(h.name)} today">${d?icon('check',16):''}</button><div class="routine-copy"><strong>${esc(h.name)}</strong><small>${n} / ${h.target} last 7 days</small></div><span class="routine-mini">${Array.from({length:7},(_,i)=>`<span class="mini-day ${habitDone(h.id,backDays(6-i))?'done':''}"></span>`).join('')}</span></div>`;}
function habitsPanel(){return `<section class="panel"><div class="panel-heading"><div><span class="eyebrow">RECURRING ACTIVITIES</span><h2>Today’s routines</h2></div><button class="inline-link" data-nav="habits">History ${icon('arrow',15)}</button></div><div class="routine-list">${store.habits.map(habitTodayCard).join('')}</div><div class="light-note">Each check-in is saved by date; activities reset daily without erasing history.</div></section>`;}
function reviewPanel(){const un=unreviewed().length,emails=pendingSuggestions().filter(s=>s.type==='email').length,cal=pendingSuggestions().filter(s=>s.type==='calendar').length;return `<section class="panel"><div class="panel-heading"><div><span class="eyebrow">APPROVAL FIRST</span><h2>Review queue</h2></div><button class="inline-link" data-nav="review">Review ${icon('arrow',15)}</button></div><div class="review-metrics"><div><strong>${un}</strong><small>Imported tasks</small></div><div><strong>${emails}</strong><small>Email proposals</small></div><div><strong>${cal}</strong><small>Calendar proposals</small></div></div><p class="light-note">No email-derived tasks or calendar events are created without approval. The proposals shown here are sample data, not live integrations.</p></section>`;}
function summaryPanel(){const n=openTasks().length;return `<div class="v3-summary"><div><small>OPEN TASKS</small><strong>${n}</strong></div><div><small>PROJECTS</small><strong>${store.projects.length}</strong></div><div><small>NEEDS REVIEW</small><strong>${unreviewed().length+pendingSuggestions().length}</strong></div><div><small>COMPLETION</small><strong>${percent(doneTasks().length,store.tasks.length)}%</strong><small>${doneTasks().length} of ${store.tasks.length} tasks</small></div></div>`;}
function dashboard(){const p=store.preferences;return `${heading('YOUR WORKSPACE','Good to see everything',`${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})} · ${store.source==='demo'?'Interactive prototype':'Your private workspace'}`,`<button class="btn btn-outline heading-button" data-nav="settings">${icon('settings',16)} Customize</button>`)}${demoLabel()}${migrationBanner()}${p.showSummary?summaryPanel():''}<div class="v3-dashboard-grid"><div>${p.showFocus?focusPanel():''}${p.showHabits?habitsPanel():''}</div><div>${p.showReview?reviewPanel():''}${p.showProjects&&p.showProjectProgress?projectsPanel():''}${p.showEmail?`<section class="panel v3-email-panel"><div class="panel-heading"><div><span class="eyebrow">OPTIONAL MODULE</span><h2>Email assistant</h2></div>${icon('inbox',17)}</div><p class="light-note">Gmail scanning is not connected. You can preview recommendations in Review, and hide this panel under Settings.</p></section>`:''}</div></div>${p.showPrivacy?`<p class="privacy-foot">${icon('info',14)} Prototype data stays in this browser. Export backups before switching devices. No Gmail, Calendar, or cloud sync connection is active.</p>`:''}`;}
function listPage(){let items=store.tasks;if(filter==='open')items=items.filter(t=>t.status==='open');if(filter==='completed')items=items.filter(t=>t.status==='completed');if(filter==='unreviewed')items=items.filter(t=>!t.reviewed&&t.status==='open');if(categoryFilter!=='all')items=items.filter(t=>t.category===categoryFilter);if(projectFilter!=='all')items=items.filter(t=>t.projectId===projectFilter);if(search.trim())items=items.filter(t=>`${t.title} ${t.notes} ${t.category} ${projectById(t.projectId)?.name||''}`.toLowerCase().includes(search.trim().toLowerCase()));items=sortTasks(items);return `${heading('TASKS','All your to-dos',`${items.length} tasks · searchable across every project`,`<button class="btn btn-outline heading-button" data-action="new-task">${icon('plus',16)} New task</button>`)}${demoLabel()}<section class="panel task-list-panel"><div class="list-toolbar"><div class="search-wrap">${icon('search',19)}<input id="task-search" type="search" placeholder="Search tasks and projects" value="${esc(search)}" /></div><select id="category-select" aria-label="Category"><option value="all">All categories</option>${store.categories.map(c=>`<option value="${esc(c.name)}" ${categoryFilter===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select id="project-select" aria-label="Project"><option value="all">All projects</option>${store.projects.map(p=>`<option value="${esc(p.id)}" ${projectFilter===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="filter-tabs">${[['open','Open'],['unreviewed','Needs review'],['completed','Completed'],['all','All']].map(([key,label])=>`<button class="filter-tab ${filter===key?'active':''}" data-action="task-filter" data-id="${key}">${label}</button>`).join('')}</div><div class="task-rows">${items.length?items.slice(0,showLimit).map(taskRow).join(''):`<div class="quiet-empty">No tasks match this filter.</div>`}</div>${items.length>showLimit?`<div class="load-more"><button class="btn btn-outline" data-action="more-tasks">Show more</button></div>`:''}</section>`;}
function projectsPage(){let projectGroups=store.categories.filter(c=>c.visible).map(c=>({...c,projects:store.projects.filter(p=>p.category===c.name)})).filter(c=>c.projects.length);return `${heading('ORGANIZE','Your projects','One dashboard, as many categories and projects as you want.',`<button class="btn btn-outline heading-button" data-action="new-project">${icon('plus',17)} New project</button>`)}${demoLabel()}<div class="project-page-actions"><button class="btn btn-primary" data-action="new-project">${icon('plus',17)} New project</button><button class="btn btn-outline" data-action="new-category">${icon('plus',17)} New category</button></div>${projectGroups.map(c=>`<section class="panel v3-category-section"><div class="panel-heading"><div><span class="eyebrow">CATEGORY</span><h2><span class="category-heading-dot" style="background:${c.color}"></span>${esc(c.name)} <span class="tiny-muted">${c.projects.length} projects</span></h2></div></div><div class="v3-project-grid">${c.projects.map(p=>projectCard(p)).join('')}</div></section>`).join('')}`;}
function projectDetail(id){const p=projectById(id);if(!p)return projectsPage();const st=projectStats(id);const tasks=store.tasks.filter(t=>t.projectId===id);return `${heading('PROJECT',p.name,`${p.category} · ${st.open} open · ${st.done} complete`,`<button class="btn btn-outline heading-button" data-nav="projects">${icon('arrow',15)} All projects</button>`)}<section class="panel v3-detail"><div class="detail-percentage"><strong>${st.total?`${st.pct}%`:'—'}</strong><span>${st.total?'Completed across project tasks':'No tasks assigned yet'}</span></div><div class="progress-track big"><div style="width:${st.pct}%"></div></div><div class="detail-actions"><button class="btn btn-outline" data-action="new-task" data-project="${esc(id)}">${icon('plus',15)} Add task</button><button class="btn btn-outline" data-action="edit-project" data-id="${esc(id)}">Edit project</button></div><div class="task-rows">${tasks.length?sortTasks(tasks).map(taskRow).join(''):`<div class="quiet-empty">No tasks assigned to this project. You can categorize OneNote items during review.</div>`}</div></section>`;}
function habitsPage(){return `${heading('ACTIVITY LOG','Routines & history','Track workouts, rides and recurring goals, with editable past entries.',`<button class="btn btn-outline heading-button" data-action="new-habit">${icon('plus',16)} New routine</button>`)}${demoLabel()}<div class="habit-page-actions"><button class="btn btn-primary" data-action="new-habit">${icon('plus',17)} Add routine</button><span class="tiny-muted">Tap a date to log details or correct history</span></div><div class="habit-cards">${store.habits.map(h=>{const count=habitCount(h.id),streak=habitStreak(h.id),stats=habitStats(h.id);const goal=Math.max(1,h.target*4),goalPct=Math.min(100,Math.round(100*stats.fourWeek/goal));const lastLogged=Array.from({length:365},(_,i)=>backDays(i)).find(day=>habitDone(h.id,day));const last=lastLogged?habitEntry(h.id,lastLogged):null;const extra=last&&typeof last==='object'&& (last.miles||last.minutes||last.elevation)?`<div class="last-entry">Last log · ${fmtDay(lastLogged)}${last.miles?` · ${Number(last.miles)} mi`:''}${last.elevation?` · ${Number(last.elevation).toLocaleString()} ft`:''}${last.minutes?` · ${Number(last.minutes)} min`:''}</div>`:'';return `<section class="panel habit-detail"><div class="habit-head"><div><span class="eyebrow">${esc(h.type||'habit').toUpperCase()} · TARGET ${h.target} DAYS / WEEK</span><h2>${esc(h.name)}</h2></div><button class="icon-button" data-action="edit-habit" data-id="${esc(h.id)}" aria-label="Edit activity">${icon('pencil',18)}</button></div><div class="habit-statline"><strong>${count}<span> / ${h.target}</span></strong><span>${streak} day streak</span><span>Last 7 days</span></div><div class="routine-figure"><div class="routine-figure-top"><span>4-week goal progress</span><strong>${goalPct}%</strong></div><div class="progress-track"><div style="width:${goalPct}%"></div></div><small>${stats.fourWeek} check-ins / ${goal} target</small></div><div class="habit-calendar" role="group" aria-label="Last 28 days of ${esc(h.name)}">${Array.from({length:28},(_,i)=>{const day=backDays(27-i);return `<button title="${day}" class="history-day ${habitDone(h.id,day)?'marked':''} ${day===today()?'today':''}" data-action="habit-day" data-id="${esc(h.id)}" data-day="${day}" aria-label="Edit ${esc(h.name)} ${day}: ${habitDone(h.id,day)?'done':'not done'}">${fromDay(day).getDate()}</button>`;}).join('')}</div><div class="weekly-bars-title">Last 12 weeks</div><div class="weekly-bars">${stats.weeks.map(w=>`<div class="weekly-bar" title="${w.count} days completed in week"><span style="height:${Math.max(4,100*w.count/7)}%" class="${w.count>=h.target?'goal-hit':''}"></span></div>`).join('')}</div>${extra}<div class="habit-bottom"><span>Tap a date for history</span><div class="habit-buttons"><button class="btn btn-outline" data-action="habit-log" data-id="${esc(h.id)}">Log details</button><button class="btn btn-outline" data-action="habit-toggle" data-id="${esc(h.id)}">${habitDone(h.id)?'Undo today':'Mark today done'}</button></div></div></section>`;}).join('')}</div>`;}
function reviewItem(s){const isCalendar=s.type==='calendar';return `<article class="review-item"><div class="review-icon">${icon(isCalendar?'calendar':'inbox',19)}</div><div class="review-item-copy"><div class="review-item-top"><b>${esc(s.title)}</b><span class="plain-chip">${isCalendar?'Calendar proposal':'Email proposal'}</span></div><small>${esc(s.detail||'Sample proposal')}</small><div class="review-item-actions"><button class="btn btn-outline" data-action="suggest-review" data-id="${esc(s.id)}">Review / edit</button><button class="btn btn-subtle" data-action="suggest-dismiss" data-id="${esc(s.id)}">Dismiss</button></div></div></article>`;}
function reviewPage(){const tasks=unreviewed(),suggestions=pendingSuggestions();return `${heading('APPROVAL INBOX','Review before anything changes',`${tasks.length} unverified imported tasks · ${suggestions.length} proposed actions`)}${demoLabel()}<div class="review-page-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">IMPORT TRIAGE</span><h2>Classify your OneNote tasks <span class="tiny-muted">${tasks.length}</span></h2></div></div><p class="inner-intro">Select multiple items to assign a project, or review them individually. No task is marked complete automatically.</p><div class="bulk-triage"><label class="bulk-all"><input type="checkbox" id="review-select-all" /> Select visible</label><select id="bulk-category" aria-label="Bulk category">${catOptions('Inbox')}</select><select id="bulk-project" aria-label="Bulk project">${projectOptions('Inbox',null)}</select><button class="btn btn-outline" data-action="bulk-review">Assign &amp; review</button></div><div class="task-rows">${tasks.length?tasks.slice(0,reviewShowLimit).map(t=>`<div class="review-task"><label class="review-label"><input type="checkbox" class="review-check" value="${esc(t.id)}"/><span><b>${esc(t.title)}</b><small>${esc(projectById(t.projectId)?.name||t.category)}</small></span></label><button class="btn btn-outline" data-action="task-edit" data-id="${esc(t.id)}">Review</button></div>`).join(''):`<div class="quiet-empty">Your imported tasks are all reviewed.</div>`}</div>${tasks.length>reviewShowLimit?`<div class="settings-actions review-more"><button class="btn btn-outline" data-action="more-review">Show more unreviewed tasks</button></div>`:''}</section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">OPTIONAL AI ASSISTANT</span><h2>Suggested actions</h2></div></div><p class="inner-intro">Demonstration proposals only. Live Gmail and Google Calendar integration is not connected, and no external actions are taken.</p><div class="v3-review-items">${suggestions.length?suggestions.map(reviewItem).join(''):`<div class="quiet-empty">No suggestions pending.</div>`}</div><p class="light-note">Approving a calendar proposal records your preference here, but does not create a real calendar event in this prototype.</p></section></div>`;}
const prefToggle=(key,name,desc)=>`<label class="setting-toggle"><span class="setting-toggle-copy"><b>${esc(name)}</b><small>${esc(desc)}</small></span><input type="checkbox" role="switch" data-pref="${key}" ${store.preferences[key]?'checked':''} /><span class="setting-switch"></span></label>`;
function settingsPage(){return `${heading('YOUR RULES','Settings','Choose what appears on your dashboard and protect your data.')}<div class="settings-grid"><section class="panel settings-panel settings-panel-wide"><div class="setting-header">${icon('layout',23)}<div><h2>Dashboard panels</h2><p>Hide cards without changing your tasks or history.</p></div></div><div class="setting-toggle-list">${prefToggle('showSummary','Overview counts','Open, completed, projects and review')}${prefToggle('showFocus','Focus tasks','Top priorities from across all projects')}${prefToggle('showProjects','Project charts','Project completion percentages')}${prefToggle('showHabits','Daily activities','Today’s workouts and rides')}${prefToggle('showReview','Review queue','Imported tasks and agent suggestions')}${prefToggle('showEmail','Email module','Show / hide email agent panel')}${prefToggle('showPrivacy','Storage reminder','Display local-only data notice')}</div></section><section class="panel settings-panel"><div class="setting-header">${icon('grid',23)}<div><h2>Categories</h2><p>Add and hide your own groups.</p></div></div><div class="category-settings-list">${store.categories.map(c=>`<div class="category-setting"><span class="category-dot" style="background:${c.color}"></span><strong>${esc(c.name)}</strong><button class="small-text-button" data-action="category-visibility" data-name="${esc(c.name)}">${c.visible?'Visible':'Hidden'}</button><button class="icon-button" data-action="edit-category" data-name="${esc(c.name)}" aria-label="Edit ${esc(c.name)}">${icon('pencil',16)}</button></div>`).join('')}</div><div class="settings-actions"><button class="btn btn-outline" data-action="new-category">${icon('plus',16)} New category</button><button class="btn btn-outline" data-action="new-project">${icon('plus',16)} New project</button></div></section><section class="panel settings-panel"><div class="setting-header">${icon('settings',23)}<div><h2>Layout defaults</h2><p>Adjust the task list and starting page.</p></div></div><div class="setting-toggle-list">${prefToggle('compactRows','Compact task rows','Show more tasks on each screen')}</div><div class="setting-controls"><label>Focus tasks<select data-pref-select="focusCount">${[3,5,8,10].map(n=>`<option ${store.preferences.focusCount===n?'selected':''} value="${n}">${n} tasks</option>`).join('')}</select></label><label>Start page<select data-pref-select="defaultView">${['dashboard','tasks','projects','habits','review'].map(k=>`<option value="${k}" ${store.preferences.defaultView===k?'selected':''}>${k}</option>`).join('')}</select></label></div></section><section class="panel settings-panel settings-panel-wide"><div class="setting-header">${icon('download',23)}<div><h2>Backup & import</h2><p>Export tasks, category hierarchy, daily activity history and approvals.</p></div></div><div class="settings-actions"><button class="btn btn-primary" data-action="export">${icon('download',17)} Export JSON backup</button><button class="btn btn-outline" data-action="import">${icon('upload',17)} Import OneNote or Task Forge JSON</button></div><p class="settings-muted">Private files are read on your device. Supports v1–v4 JSON with preview, duplicate detection and optional project assignment. Never upload private backups to a public repository.</p></section><section class="panel settings-panel"><div class="setting-header">${icon('info',23)}<div><h2>Integrations</h2><p>Preview only · Approval required by design</p></div></div><div class="integration-status"><b>Gmail</b><span>Not connected</span></div><div class="integration-status"><b>Google Calendar</b><span>Not connected</span></div><div class="integration-status"><b>Cloud sync</b><span>Not connected</span></div><p class="settings-muted">No background scanning or external actions. Gmail and Calendar remain proposal-only mockups until separately authorized.</p></section><section class="panel settings-panel"><div class="setting-header">${icon('rotate',23)}<div><h2>Workspace migration</h2><p>Copy an existing v3 workspace without changing the original.</p></div></div><div class="settings-actions"><button class="btn btn-outline" data-action="migrate-v3">Review copy from v3</button><button class="btn btn-outline" data-action="reset-prototype">Reset v4 sample data</button></div><p class="settings-muted">Copy is available only if v3 data exists in this browser. Export a backup before reset.</p></section></div>`;}
function chrome(){const open=openTasks().length;$('#nav-open-count').textContent=open;$('#nav-inbox-count').textContent=unreviewed().length+pendingSuggestions().length;$$('[data-nav]').forEach(el=>{let selected=el.dataset.nav===view||(view==='project-detail'&&el.dataset.nav==='projects');el.classList.toggle('selected',selected);if(selected)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});}
let detailId='';
function render(){chrome();const output= view==='dashboard'?dashboard():view==='tasks'?listPage():view==='projects'?projectsPage():view==='project-detail'?projectDetail(detailId):view==='habits'?habitsPage():view==='review'?reviewPage():view==='settings'?settingsPage():dashboard();$('#main').innerHTML=output;hydrateIcons(document);}
function nav(name){view=name;filter='open';categoryFilter='all';projectFilter='all';search='';render();window.scrollTo(0,0);}
function updateTask(id,patch){const i=store.tasks.findIndex(t=>t.id===id);if(i<0)return;store.tasks[i]=normalizeTask({...store.tasks[i],...patch,updatedAt:new Date().toISOString()});persist();render();}
function taskToggle(id){const t=store.tasks.find(x=>x.id===id);if(!t)return;const completed=t.status!=='completed';updateTask(id,{status:completed?'completed':'open',completedAt:completed?new Date().toISOString():null,reviewed:true});}
function habitToggle(id,day=today()){if(!store.history[id])store.history[id]={};if(habitDone(id,day))delete store.history[id][day];else store.history[id][day]={completed:true,minutes:null,miles:null,elevation:null,note:''};persist();render();}
function editor(markup,postRender){$('#modal-root').innerHTML=`<div class="modal-shade" data-action="modal-close"><div class="editor v3-editor" role="dialog" aria-modal="true">${markup}</div></div>`;hydrateIcons($('#modal-root'));postRender?.();}
const modalHeader=(title,subtitle)=>`<div class="editor-head"><div><span class="eyebrow">${esc(subtitle)}</span><h2>${esc(title)}</h2></div><button class="icon-button" data-action="modal-close" aria-label="Close">${icon('close',20)}</button></div>`;
const modalFooter=(label)=>`<div class="editor-actions"><button type="button" class="btn btn-subtle" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">${esc(label)}</button></div>`;
const catOptions=(selected)=>store.categories.map(c=>`<option ${c.name===selected?'selected':''} value="${esc(c.name)}">${esc(c.name)}</option>`).join('');
const projectOptions=(category,id)=>`<option value="">No specific project</option>${store.projects.map(p=>`<option ${p.id===id?'selected':''} value="${esc(p.id)}">${esc(p.name)} · ${esc(p.category)}</option>`).join('')}`;
function taskEditor(id=null,projectId=null){const existing=id?store.tasks.find(t=>t.id===id):null,project=projectById(projectId),t=existing||{title:'',category:project?.category||'Inbox',projectId:projectId||null,priority:'normal',reviewed:true,status:'open',notes:'',dueDate:''};editor(`${modalHeader(existing?'Review / edit task':'New task','PROJECT TASK')}<form id="task-form"><div class="form-body"><label>Task name<input name="title" required maxlength="260" value="${esc(t.title)}" placeholder="What needs doing?" /></label><div class="form-pair"><label>Category<select name="category">${catOptions(t.category)}</select></label><label>Priority<select name="priority">${['low','normal','high','urgent'].map(k=>`<option ${k===t.priority?'selected':''} value="${k}">${k}</option>`).join('')}</select></label></div><label>Project<select name="projectId">${projectOptions(t.category,t.projectId)}</select></label><div class="form-pair"><label>Due date<input type="date" name="dueDate" value="${esc(t.dueDate||'')}" /></label><label>Status<select name="status"><option value="open" ${t.status==='open'?'selected':''}>Open</option><option value="completed" ${t.status==='completed'?'selected':''}>Completed</option></select></label></div><label>Notes<textarea name="notes" rows="4">${esc(t.notes||'')}</textarea></label><label class="form-checkbox"><input type="checkbox" name="reviewed" ${t.reviewed?'checked':''} /> Reviewed and still relevant</label>${t.source==='OneNote PDF'?`<p class="source-detail">Imported from OneNote · source item ${t.sourceIndex||'unknown'}</p>`:''}</div>${modalFooter(existing?'Save task':'Add task')}</form>`,()=>{const f=$('#task-form');f.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(f),title=String(fd.get('title')||'').trim();if(!title)return;const p=projectById(fd.get('projectId')),nowDone=fd.get('status')==='completed';const task=normalizeTask({...t,id:existing?.id||uid(),title,category:p?.category||fd.get('category'),projectId:fd.get('projectId')||null,priority:fd.get('priority'),status:fd.get('status'),reviewed:fd.has('reviewed'),dueDate:fd.get('dueDate')||null,notes:fd.get('notes'),source:existing?.source||'Manual',completedAt:nowDone?(existing?.completedAt||new Date().toISOString()):null});if(existing)store.tasks=store.tasks.map(x=>x.id===existing.id?task:x);else store.tasks.unshift(task);persist();closeEditor();render();toast('Task saved');});});}
function categoryEditor(name=null){const c=store.categories.find(x=>x.name===name)||{name:'',color:'#8eaeb5'};editor(`${modalHeader(name?'Edit category':'Add category','CUSTOM GROUP')}<form id="category-form"><div class="form-body"><label>Name<input name="name" maxlength="70" required value="${esc(c.name)}" placeholder="e.g. Email, Side Projects"/></label><label>Marker color<input name="color" type="color" value="${esc(c.color)}" /></label><p class="light-note">Categories organize projects. Hiding one only hides its dashboard cards; it never deletes tasks.</p></div>${modalFooter(name?'Save category':'Create category')}</form>`,()=>{$('#category-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target),next=String(fd.get('name')||'').trim(),color=fd.get('color');if(!next)return;if(store.categories.some(x=>x.name.toLowerCase()===next.toLowerCase()&&x.name!==name)){toast('Category already exists',true);return;}if(name){const old=store.categories.find(x=>x.name===name);old.name=next;old.color=color;store.projects.filter(p=>p.category===name).forEach(p=>p.category=next);store.tasks.filter(t=>t.category===name).forEach(t=>t.category=next);}else store.categories.push(normalizeCategory({name:next,color,icon:'grid'}));persist();closeEditor();render();toast('Category saved');});});}
function projectEditor(id=null){const original=projectById(id),p=original||{name:'',category:store.categories[0]?.name||'Inbox'};editor(`${modalHeader(original?'Edit project':'Create project','PROJECT')}<form id="project-form"><div class="form-body"><label>Project name<input name="name" maxlength="90" required value="${esc(p.name)}" placeholder="e.g. Polaris Snowmobile" /></label><label>Category<select name="category">${catOptions(p.category)}</select></label><p class="light-note">Every project can have its own progress chart and an unlimited list of tasks.</p></div>${modalFooter(original?'Save project':'Create project')}</form>`,()=>{$('#project-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target);const name=String(fd.get('name')||'').trim(),category=fd.get('category');if(!name)return;if(original){original.name=name;original.category=category;store.tasks.filter(t=>t.projectId===original.id).forEach(t=>t.category=category);}else store.projects.push(normalizeProject({name,category}));persist();closeEditor();render();toast('Project saved');});});}
function habitLogEditor(id,day=today()){
 const h=store.habits.find(x=>x.id===id);if(!h)return;
 const raw=habitEntry(id,day),entry=raw&&typeof raw==='object'?raw:{completed:habitDone(id,day),minutes:null,miles:null,elevation:null,note:''};
 editor(`${modalHeader('Log '+h.name,'ACTIVITY · '+day)}<form id="habit-log-form"><div class="form-body"><label>Date<input type="date" name="day" required value="${esc(day)}" /></label><label class="form-checkbox"><input type="checkbox" name="completed" ${entry.completed?'checked':''}/> Completed this activity</label>${h.type!=='habit'?`<label>Duration (minutes)<input name="minutes" type="number" min="0" max="1440" step="1" value="${entry.minutes??''}" placeholder="Optional" /></label>`:''}${h.type==='ride'?`<div class="form-pair"><label>Distance (miles)<input name="miles" type="number" min="0" max="500" step="0.1" value="${entry.miles??''}" placeholder="Optional" /></label><label>Elevation gain (ft)<input name="elevation" type="number" min="0" max="50000" step="1" value="${entry.elevation??''}" placeholder="Optional" /></label></div>`:''}<label>Notes<textarea name="note" rows="3" maxlength="1200" placeholder="How did it go?">${esc(entry.note||'')}</textarea></label><p class="light-note">Every date is stored separately. Unchecking completion removes that day's record. Garmin is not connected.</p></div>${modalFooter('Save log')}</form>`,()=>{$('#habit-log-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target),date=String(fd.get('day')||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>today()){toast('Choose today or a past date',true);return;}if(!store.history[id])store.history[id]={};if(!fd.has('completed'))delete store.history[id][date];else {const num=n=>{const raw=fd.get(n);return raw===''||raw==null?null:Math.max(0,Number(raw))};store.history[id][date]={completed:true,minutes:num('minutes'),miles:num('miles'),elevation:num('elevation'),note:String(fd.get('note')||'').slice(0,1200)};}persist();closeEditor();render();toast('Activity history saved');});});
}
function habitEditor(id=null){const h=store.habits.find(x=>x.id===id)||{name:'',target:5};editor(`${modalHeader(id?'Edit activity':'New activity','DAILY HISTORY')}<form id="habit-form"><div class="form-body"><label>Activity name<input name="name" maxlength="90" required value="${esc(h.name)}" placeholder="e.g. Workout" /></label><label>Activity type<select name="type">${[['habit','Simple check-in'],['workout','Workout / training'],['ride','Mountain bike ride']].map(([val,label])=>`<option value="${val}" ${h.type===val?'selected':''}>${label}</option>`).join('')}</select></label><label>Target days per week<select name="target">${[1,2,3,4,5,6,7].map(n=>`<option ${n===h.target?'selected':''} value="${n}">${n} / week</option>`).join('')}</select></label><p class="light-note">Check-ins are stored by date and are included in your backups.</p></div>${modalFooter('Save routine')}</form>`,()=>{$('#habit-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target),name=String(fd.get('name')||'').trim();if(!name)return;const o=normalizeHabit({...h,id:id||uid(),name,target:Number(fd.get('target')),type:fd.get('type')});if(id)store.habits=store.habits.map(x=>x.id===id?o:x);else store.habits.push(o);persist();closeEditor();render();toast('Routine saved');});});}
function suggestEditor(id){const s=store.suggestions.find(x=>x.id===id);if(!s)return;editor(`${modalHeader('Review suggestion','SAMPLE ONLY · APPROVAL REQUIRED')}<form id="suggest-form"><div class="form-body"><p class="light-note">${esc(s.detail)}. This is not a live Gmail or Calendar suggestion.</p><label>Suggested action<input required maxlength="260" name="title" value="${esc(s.title)}" /></label><label>Category<select name="category">${catOptions(s.category)}</select></label><label>Project<select name="projectId">${projectOptions(s.category,s.projectId)}</select></label><p class="light-note">${s.type==='calendar'?'Approving will record a local decision only; it will NOT create an event on Google Calendar.':'Approving will create a new local task in the selected category.'}</p></div><div class="editor-actions"><button type="button" class="btn btn-subtle" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">${s.type==='calendar'?'Approve locally':'Approve & add task'}</button></div></form>`,()=>{$('#suggest-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target),title=String(fd.get('title')||'').trim(),p=projectById(fd.get('projectId'));if(!title)return;s.status='approved';if(s.type!=='calendar')store.tasks.unshift(normalizeTask({id:`suggested-${s.id}`,title,category:p?.category||fd.get('category'),projectId:p?.id||null,status:'open',reviewed:true,priority:s.priority,source:'Sample suggestion'}));persist();closeEditor();render();toast(s.type==='calendar'?'Approved locally; no calendar event created':'Approved. Task added locally.');});});}
function closeEditor(){$('#modal-root').innerHTML='';pendingImport=null;}
function previewImport(parsed,label='Selected JSON'){
 if(![1,2,3,4].includes(Number(parsed?.schemaVersion))||!Array.isArray(parsed.tasks))throw Error('Unsupported Task Forge JSON');
 if(parsed.tasks.length>20000)throw Error('Maximum 20,000 tasks per import');
 const ids=new Set();const tasks=parsed.tasks.map(normalizeTask).filter(t=>{if(ids.has(t.id))return false;ids.add(t.id);return true;});
 const existingIds=new Set(store.tasks.map(t=>t.id));const dupIds=tasks.filter(t=>existingIds.has(t.id)).length;
 pendingImport={parsed,tasks};
 editor(`${modalHeader('Review import','NO CHANGES UNTIL CONFIRMED')}<div class="form-body"><p><b>${esc(label)}</b></p><div class="settings-stats"><div><b>${tasks.length}</b><small>Entries</small></div><div><b>${tasks.filter(t=>t.status==='open').length}</b><small>Open</small></div><div><b>${dupIds}</b><small>Matching IDs</small></div></div><p class="light-note">For a project-specific OneNote conversion, choose its destination below. Assigning a project keeps subtasks and imported checkbox states.</p><label>Assign all imported tasks to project (optional)<select id="import-project">${projectOptions('Inbox',null)}</select></label><p class="light-note">Merge skips matching task IDs and identical titles in the same project. Replace restores the backup's tasks; if this is a v3/v4 backup, it also restores projects, categories and activity history. Your original v3 data is never changed.</p><div class="settings-actions"><button type="button" class="btn btn-primary" data-action="import-confirm" data-mode="merge">Merge new items</button><button type="button" class="btn btn-outline" data-action="import-confirm" data-mode="replace">Replace workspace</button></div><p class="light-note">Export a JSON backup before replacing your current workspace.</p></div>`);
}
function importJSON(file){if(!file)return;if(file.size>10*1024*1024){toast('10 MB import limit',true);return;}file.text().then(raw=>previewImport(JSON.parse(raw),file.name)).catch(e=>toast(`Import failed: ${e.message}`,true));}
function migrateV3(){const raw=localStorage.getItem('task-forge-v3-prototype');if(!raw){toast('No v3 workspace found in this browser',true);return;}try{previewImport(JSON.parse(raw),'Existing v3 workspace on this device');}catch(e){toast('Unable to read v3 data: '+e.message,true);}}
function commitImport(mode){if(!pendingImport)return;const {parsed,tasks}=pendingImport,oldStore=store,chosenProject=projectById($('#import-project')?.value);const normalized=tasks.map(t=>chosenProject?normalizeTask({...t,category:chosenProject.category,projectId:chosenProject.id,reviewed:false}):t);
 if(mode==='replace'){
   const next={...store,source:String(parsed.source||'Imported file').slice(0,100),tasks:normalized,importedAt:new Date().toISOString()};
   if(parsed.schemaVersion>=3){next.categories=(parsed.categories||CATEGORIES).map(normalizeCategory);next.projects=(parsed.projects||PROJECTS).map(normalizeProject);next.habits=(parsed.habits||DEMO_HABITS).map(normalizeHabit);next.history=parsed.history||{};next.suggestions=(parsed.suggestions||[]).map(normalizeSuggestion);next.preferences=normalizePrefs(parsed.preferences);}
   else if(store.source==='demo'){next.suggestions=[];next.history={};}
   store=next;
 }else{
   if(store.source==='demo'){store.tasks=[];store.suggestions=[];store.history={};store.source=String(parsed.source||'Imported file').slice(0,100);}
   // Ensure projects from backups exist before adding their tasks.
   if(parsed.schemaVersion>=3){const cats=new Set(store.categories.map(c=>c.name));(parsed.categories||[]).forEach(c=>{if(!cats.has(c.name)){store.categories.push(normalizeCategory(c));cats.add(c.name);}});const projects=new Set(store.projects.map(p=>p.id));(parsed.projects||[]).forEach(p=>{if(!projects.has(p.id)){store.projects.push(normalizeProject(p));projects.add(p.id);}});if(oldStore.source==='demo'){store.habits=(parsed.habits||store.habits).map(normalizeHabit);store.history=parsed.history||{};}}
   const ids=new Set(store.tasks.map(t=>t.id)),names=new Set(store.tasks.map(t=>`${normTitle(t.title)}|${t.projectId||t.category}`));let skipped=0;
   for(const t of normalized){const key=`${normTitle(t.title)}|${t.projectId||t.category}`;if(ids.has(t.id)||names.has(key)){skipped++;continue;}store.tasks.push(t);ids.add(t.id);names.add(key);}
   if(skipped)toast(`${skipped} matching tasks skipped`);
 }
 pendingImport=null;closeEditor();persist();reviewShowLimit=50;nav('review');toast('Import saved. Review the tasks before marking them relevant.');
}
function exportJSON(){const blob=new Blob([JSON.stringify({...store,schemaVersion:SCHEMA_VERSION,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const name=`task-forge-v4-backup-${today()}.json`;if(typeof File==='function'&&typeof navigator.share==='function'&&typeof navigator.canShare==='function'){const file=new File([blob],name,{type:'application/json'});if(navigator.canShare({files:[file]})){navigator.share({files:[file],title:'Task Forge backup'}).catch(e=>{if(e?.name!=='AbortError')fallbackDownload(blob,name);});return;}}fallbackDownload(blob,name);}
function fallbackDownload(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),5000);toast('Backup exported to your device');}
function action(el){const cmd=el.dataset.action,id=el.dataset.id;
 if(cmd==='new-task')return taskEditor(null,el.dataset.project||null);
 if(cmd==='task-edit')return taskEditor(id);
 if(cmd==='task-toggle')return taskToggle(id);
 if(cmd==='new-project')return projectEditor();
 if(cmd==='edit-project')return projectEditor(id);
 if(cmd==='project-open'){detailId=id;view='project-detail';render();window.scrollTo(0,0);return;}
 if(cmd==='new-category')return categoryEditor();
 if(cmd==='edit-category')return categoryEditor(el.dataset.name);
 if(cmd==='category-visibility'){const c=store.categories.find(x=>x.name===el.dataset.name);if(c){c.visible=!c.visible;persist();render();}return;}
 if(cmd==='new-habit')return habitEditor();
 if(cmd==='edit-habit')return habitEditor(id);
 if(cmd==='habit-day')return habitLogEditor(id,el.dataset.day);
 if(cmd==='habit-log')return habitLogEditor(id);
 if(cmd==='habit-toggle')return habitToggle(id);
 if(cmd==='task-filter'){filter=id;render();return;}
 if(cmd==='suggest-review')return suggestEditor(id);
 if(cmd==='suggest-dismiss'){const s=store.suggestions.find(x=>x.id===id);if(s){s.status='dismissed';persist();render();toast('Suggestion dismissed');}return;}
 if(cmd==='import'){ $('#import-file').click();return;}
 if(cmd==='import-confirm')return commitImport(el.dataset.mode);
 if(cmd==='export')return exportJSON();
 if(cmd==='more-tasks'){showLimit+=100;render();return;}
 if(cmd==='more-review'){reviewShowLimit+=50;render();return;}
 if(cmd==='migrate-v3')return migrateV3();
 if(cmd==='bulk-review'){const ids=$$('.review-check:checked').map(n=>n.value);if(!ids.length){toast('Select one or more tasks to review',true);return;}const p=projectById($('#bulk-project')?.value),cat=p?.category||$('#bulk-category')?.value||'Inbox';const selected=new Set(ids);store.tasks=store.tasks.map(t=>selected.has(t.id)?normalizeTask({...t,projectId:p?.id||null,category:cat,reviewed:true,updatedAt:new Date().toISOString()}):t);persist();render();toast(`${ids.length} tasks categorized and reviewed`);return;}
 if(cmd==='reset-prototype'){if(confirm('Reset the v4 workspace? This deletes ONLY v4 local data. Export a backup first.')){store=demoState();persist();nav('dashboard');}return;}
 if(cmd==='modal-close')return closeEditor();
}
document.addEventListener('click',evt=>{const b=evt.target.closest('[data-nav]');if(b){nav(b.dataset.nav);return;}const a=evt.target.closest('[data-action]');if(a){if(a.classList.contains('modal-shade')&&evt.target!==a)return;action(a);}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='import-file'){importJSON(el.files[0]);el.value='';}if(el.dataset.pref){store.preferences[el.dataset.pref]=el.checked;persist();render();}if(el.dataset.prefSelect){store.preferences[el.dataset.prefSelect]=el.dataset.prefSelect==='focusCount'?Number(el.value):el.value;persist();render();}if(el.id==='review-select-all')$$('.review-check').forEach(n=>n.checked=el.checked);if(el.id==='category-select'){categoryFilter=el.value;render();}if(el.id==='project-select'){projectFilter=el.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='task-search'){search=e.target.value;const cur=e.target.selectionStart;render();const el=$('#task-search');el.focus();try{el.setSelectionRange(cur,cur);}catch{}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeEditor();if(e.key==='Enter'&&e.target.matches('.task-body[role="button"]'))taskEditor(e.target.closest('[data-id]').dataset.id);});
render();
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));